<path d="M-15 -27 Q0 -32 15 -27 L14 6 Q15 24 11 33 Q0 39 -11 33 Q-15 24 -14 6 Z" fill="url(#g_int_cream)" stroke="@vet1O" stroke-width="0.8"/>
